(window.CARDS = window.CARDS || {}).film = [{"name":"Крёстный отец","emoji":"🍊","meta":["криминальная драма","1972","Фрэнсис Форд Коппола"],"description":"О сицилийской мафиозной семье Корлеоне в Нью-Йорке 1940-х, где на смену стареющему дону приходит его младший сын. Экранизация романа Марио Пьюзо стала эталоном гангстерского кино и разошлась на цитаты.","fact":"Фраза «Я сделаю ему предложение, от которого он не сможет отказаться» вошла в число самых известных в истории кино.","wiki_en":"The Godfather"},{"name":"Побег из Шоушенка","emoji":"⛓️","meta":["драма","1994","Фрэнк Дарабонт"],"description":"История банкира, несправедливо осуждённого за убийство жены и отправленного в суровую тюрьму, где он находит опору в дружбе с сокамерником. Экранизация повести Стивена Кинга долгие годы держится на первом месте в зрительском рейтинге IMDb.","fact":"В прокате фильм провалился, но стал одним из самых пересматриваемых благодаря повторным показам по телевидению и видео.","wiki_en":"The Shawshank Redemption"},{"name":"Криминальное чтиво","emoji":"💼","meta":["криминальная комедия","1994","Квентин Тарантино"],"description":"Несколько переплетённых историй из жизни бандитов, боксёра и парочки грабителей в Лос-Анджелесе, рассказанных не по порядку событий. Фильм прославился рваной нелинейной структурой, дерзкими диалогами и саундтреком, а также вернул на большие экраны Джона Траволту.","fact":"Содержимое светящегося чемоданчика в фильме так и не показывают — зрителям предлагают додумать его самим.","wiki_en":"Pulp Fiction"},{"name":"Форрест Гамп","emoji":"🍫","meta":["драма","1994","Роберт Земекис"],"description":"Простодушный парень из Алабамы случайно оказывается участником ключевых событий американской истории второй половины XX века. Фильм соединяет наивный юмор с ностальгией и стал одним из самых цитируемых в поп-культуре.","fact":"Фраза Форреста про коробку шоколадных конфет — «никогда не знаешь, что тебе попадётся» — стала расхожей идиомой.","wiki_en":"Forrest Gump"},{"name":"Матрица","emoji":"💊","meta":["фантастика","1999","Вачовски"],"description":"Хакер узнаёт, что привычный мир — это компьютерная симуляция, а настоящая реальность выглядит совсем иначе, и присоединяется к восстанию против машин. Фильм произвёл революцию в визуальных эффектах благодаря технике «пуля-тайм» и задал моду на чёрные кожаные плащи.","fact":"Выбор между красной и синей таблеткой из фильма превратился в устойчивый культурный образ выбора между удобной ложью и неприятной правдой.","wiki_en":"The Matrix"},{"name":"Бойцовский клуб","emoji":"🧼","meta":["драма","1999","Дэвид Финчер"],"description":"Безымянный офисный работник, страдающий от бессонницы и апатии, знакомится с харизматичным торговцем мылом и вместе с ним организует подпольные бойцовские клубы. Экранизация романа Чака Паланика поначалу разочаровала критиков, но со временем обрела статус культового фильма.","fact":"Первое правило Бойцовского клуба в фильме — никому не рассказывать о Бойцовском клубе — стало устойчивым мемом далеко за пределами кино.","wiki_en":"Fight Club"},{"name":"Начало","emoji":"🌀","meta":["фантастика","2010","Кристофер Нолан"],"description":"Специалист по проникновению в чужие сны получает задание не украсть идею, а наоборот — незаметно её внедрить, спускаясь для этого на несколько уровней сновидений одновременно. Сложная структура фильма с вложенными снами и открытым финалом породила споры зрителей.","fact":"Волчок, который герой крутит на протяжении фильма, стал символом неоднозначности финала — каждый решает сам, остановился он или нет.","wiki_en":"Inception"},{"name":"Интерстеллар","emoji":"🚀","meta":["фантастика","2014","Кристофер Нолан"],"description":"Из-за экологической катастрофы человечество на грани вымирания, и бывший пилот отправляется через червоточину искать пригодную для жизни планету, оставляя дочь на Земле. Фильм известен научной консультацией физика Кипа Торна и визуализацией чёрной дыры.","fact":"Из-за эффектов замедления времени рядом с чёрной дырой один час на далёкой планете в фильме равен годам на Земле.","wiki_en":"Interstellar (film)"},{"name":"Тёмный рыцарь","emoji":"🦇","meta":["боевик","2008","Кристофер Нолан"],"description":"Бэтмен, комиссар Гордон и прокурор Харви Дент пытаются остановить анархиста-преступника по прозвищу Джокер, который бросает вызов всем правилам Готэма. Фильм переосмыслил супергеройское кино как мрачный криминальный триллер и получил признание критиков.","fact":"Посмертный «Оскар» за роль Джокера получил Хит Леджер, умерший до премьеры фильма.","wiki_en":"The Dark Knight"},{"name":"Властелин колец: Братство Кольца","emoji":"💍","meta":["фэнтези","2001","Питер Джексон"],"description":"Хоббит Фродо получает опасное поручение — уничтожить Кольцо Всевластия, и вместе с разношёрстным отрядом отправляется в долгий путь через Средиземье. Первая часть трилогии по роману Толкина поразила масштабом съёмок в Новой Зеландии и вниманием к деталям.","fact":"Съёмки всех трёх фильмов трилогии проходили практически одновременно на протяжении более года.","wiki_en":"The Lord of the Rings: The Fellowship of the Ring"},{"name":"Гарри Поттер и философский камень","emoji":"⚡","meta":["фэнтези","2001","Крис Коламбус"],"description":"Мальчик-сирота узнаёт, что он волшебник, и отправляется учиться в школу магии Хогвартс, где заводит друзей и раскрывает семейную тайну. Первый фильм франшизы по книгам Джоан Роулинг положил начало одной из самых кассовых киносерий в истории.","fact":"На роли трёх главных героев создатели просмотрели тысячи детей по всей Великобритании.","wiki_en":"Harry Potter and the Philosopher's Stone (film)"},{"name":"Звёздные войны. Эпизод IV: Новая надежда","emoji":"⚔️","meta":["фантастика","1977","Джордж Лукас"],"description":"Молодой фермер с пустынной планеты оказывается втянут в войну повстанцев против галактической Империи и узнаёт о своём предназначении. Фильм Джорджа Лукаса произвёл революцию в визуальных эффектах и звуке и породил одну из крупнейших франшиз в истории кино.","fact":"Перед премьерой в успех фильма почти никто не верил, а прокатчики выпускали его ограниченным числом копий.","wiki_en":"Star Wars (film)"},{"name":"Титаник","emoji":"🚢","meta":["мелодрама","1997","Джеймс Кэмерон"],"description":"На борту роскошного и, как считалось, непотопляемого лайнера вспыхивает любовь между бедным художником и девушкой из высшего общества, а корабль тем временем идёт навстречу катастрофе. Фильм долгое время оставался самым кассовым в истории.","fact":"Песня My Heart Will Go On в исполнении Селин Дион стала одной из самых узнаваемых кинобаллад в истории.","wiki_en":"Titanic (1997 film)"},{"name":"Аватар","emoji":"🌿","meta":["фантастика","2009","Джеймс Кэмерон"],"description":"Бывший морпех управляет искусственным телом гуманоида-на'ви, чтобы разведать ресурсы на планете Пандора, но постепенно проникается культурой её жителей. Фильм произвёл впечатление масштабным применением 3D и технологии захвата движения, создав целый инопланетный мир.","fact":"Фильм стал самым кассовым в мировом прокате и удерживал этот рекорд много лет.","wiki_en":"Avatar (2009 film)"},{"name":"Парк юрского периода","emoji":"🦖","meta":["фантастика","1993","Стивен Спилберг"],"description":"На уединённом острове учёные с помощью древней ДНК воссоздают динозавров для парка развлечений, но система безопасности выходит из строя, и гости оказываются один на один с хищниками. Фильм Спилберга совершил прорыв в компьютерной графике.","fact":"Часть динозавров в фильме — это аниматронные модели в натуральную величину, а не только компьютерная графика.","wiki_en":"Jurassic Park (film)"},{"name":"Челюсти","emoji":"🦈","meta":["триллер","1975","Стивен Спилберг"],"description":"Небольшой курортный городок оказывается терроризирован гигантской белой акулой, и шериф вместе с океанологом и охотником отправляется в море, чтобы её остановить. Фильм Спилберга считается первым по-настоящему летним блокбастером.","fact":"Механическая акула на площадке постоянно ломалась, из-за чего Спилбергу пришлось дольше держать хищника за кадром — и это усилило напряжение.","wiki_en":"Jaws (film)"},{"name":"Инопланетянин","emoji":"🛸","meta":["фантастика","1982","Стивен Спилберг"],"description":"Мальчик находит в саду забытого на Земле инопланетянина и, прячась от взрослых, помогает ему связаться с домом и вернуться на корабль. Тёплая семейная история Спилберга о дружбе и взрослении стала одним из самых любимых фильмов о пришельцах.","fact":"Сцена полёта на велосипеде на фоне луны стала одним из самых узнаваемых кадров в истории кино.","wiki_en":"E.T. the Extra-Terrestrial"},{"name":"Индиана Джонс: В поисках утраченного ковчега","emoji":"🤠","meta":["приключения","1981","Стивен Спилберг"],"description":"Археолог и авантюрист по прозвищу Индиана Джонс соревнуется с нацистами в поисках библейского Ковчега Завета, обладающего сверхъестественной силой. Фильм соединил дух приключенческих сериалов прошлого с современными на тот момент трюками и погонями.","fact":"Знаменитую сцену с фехтованием против мечника создатели придумали экспромтом, потому что исполнитель главной роли неважно себя чувствовал.","wiki_en":"Raiders of the Lost Ark"},{"name":"Назад в будущее","emoji":"🚗","meta":["фантастика","1985","Роберт Земекис"],"description":"Подросток на переделанном в машину времени автомобиле случайно попадает из 1985 года в 1955-й, где встречает своих будущих родителей молодыми и рискует помешать собственному рождению. Фильм стал классикой жанра путешествий во времени.","fact":"Машиной времени в фильме стал серийный автомобиль DeLorean с характерными дверями, поднимающимися вверх.","wiki_en":"Back to the Future"},{"name":"Терминатор 2: Судный день","emoji":"🤖","meta":["фантастика","1991","Джеймс Кэмерон"],"description":"Робот-терминатор прежней модели теперь защищает мальчика-подростка от нового, более совершенного киборга из жидкого металла, присланного изменить будущее. Сиквел прославился прорывными на тот момент спецэффектами трансформации жидкого металла.","fact":"Фраза I'll be back из первого фильма стала фирменной для героя Арнольда Шварценеггера на десятилетия вперёд.","wiki_en":"Terminator 2: Judgment Day"},{"name":"Чужой","emoji":"👽","meta":["ужасы","1979","Ридли Скотт"],"description":"Экипаж грузового космического корабля откликается на сигнал бедствия с неизвестной планеты и невольно приносит на борт смертоносного инопланетного хищника. Фильм Ридли Скотта соединил космическую фантастику с эстетикой хоррора.","fact":"Дизайн ксеноморфа создал швейцарский художник Ханс Гигер, известный своим мрачным биомеханическим стилем.","wiki_en":"Alien (film)"},{"name":"Бегущий по лезвию","emoji":"🌃","meta":["фантастика","1982","Ридли Скотт"],"description":"В мрачном будущем детектив охотится на беглых биоинженерных репликантов, почти неотличимых от людей, и постепенно задумывается о природе собственного сознания. Экранизация романа Филипа Дика задала визуальный канон киберпанка на десятилетия вперёд.","fact":"При выходе в прокат фильм провалился в кассах и лишь позже был переоценён как один из главных фантастических фильмов XX века.","wiki_en":"Blade Runner"},{"name":"Крепкий орешек","emoji":"🏢","meta":["боевик","1988","Джон Мактирнан"],"description":"Нью-йоркский полицейский в одиночку противостоит банде вооружённых преступников, захвативших небоскрёб на рождественской вечеринке, где находится его жена. Фильм задал канон боевиков «один герой против группы врагов в замкнутом пространстве» на годы вперёд.","fact":"Фраза Yippee-ki-yay героя Брюса Уиллиса стала одной из самых узнаваемых в жанре боевиков.","wiki_en":"Die Hard"},{"name":"Один дома","emoji":"🎄","meta":["комедия","1990","Крис Коламбус"],"description":"Восьмилетнего мальчика по ошибке забывают дома, когда семья улетает на Рождество в Европу, и ему приходится в одиночку защищать дом от двух незадачливых грабителей. Семейная комедия с изобретательными ловушками стала одним из самых узнаваемых рождественских фильмов.","fact":"Больше двух десятилетий фильм оставался самой кассовой комедией с живыми актёрами в мировом прокате.","wiki_en":"Home Alone"},{"name":"Красотка","emoji":"👠","meta":["романтическая комедия","1990","Гарри Маршалл"],"description":"Богатый бизнесмен нанимает девушку с улицы в компаньонки на неделю деловых встреч, и между ними неожиданно вспыхивает настоящее чувство. Современная версия сюжета о Золушке сделала звездой Джулию Робертс и стала одной из самых кассовых романтических комедий.","fact":"Изначально сценарий был мрачной драмой о жизни на улице и лишь после переработки студией превратился в романтическую комедию со счастливым финалом.","wiki_en":"Pretty Woman"},{"name":"Грязные танцы","emoji":"💃","meta":["музыкальная мелодрама","1987","Эмиль Ардолино"],"description":"На летнем курорте девушка из благополучной семьи влюбляется в танцора из бедной среды и тайком готовится вместе с ним к ответственному выступлению. Фильм прославился танцевальными номерами и саундтреком, включая знаменитую песню (I've Had) The Time of My Life.","fact":"Финальный подъём партнёрши над головой стал одним из самых пародируемых танцевальных движений в кино.","wiki_en":"Dirty Dancing"},{"name":"Привидение","emoji":"👻","meta":["мелодрама","1990","Джерри Цукер"],"description":"Убитый мужчина остаётся на земле призраком и с помощью мошенницы-медиума пытается защитить свою возлюбленную и раскрыть обстоятельства собственной смерти. Фильм соединил мистику с трогательной любовной драмой и подарил кино одну из самых цитируемых сцен с гончарным кругом.","fact":"Песня Unchained Melody, звучащая в знаменитой сцене с глиной, снова стала хитом спустя четверть века после оригинальной записи The Righteous Brothers.","wiki_en":"Ghost (1990 film)"},{"name":"Молчание ягнят","emoji":"🦋","meta":["триллер","1991","Джонатан Демме"],"description":"Молодая слушательница академии ФБР консультируется с заключённым психиатром-каннибалом Ганнибалом Лектером, чтобы выйти на след другого серийного убийцы. Фильм стал одним из немногих триллеров, получивших «Оскар» за лучший фильм.","fact":"Энтони Хопкинс провёл в кадре в роли Лектера чуть более пятнадцати минут, но этого хватило, чтобы получить «Оскар» за главную роль.","wiki_en":"The Silence of the Lambs"},{"name":"Семь","emoji":"📦","meta":["триллер","1995","Дэвид Финчер"],"description":"Два детектива, один на пороге отставки, другой только начинающий службу, расследуют серию убийств, в которых преступник вдохновляется семью смертными грехами. Мрачная атмосфера постоянного дождя и жёсткая режиссура Финчера сделали фильм эталоном криминального триллера 1990-х.","fact":"Финал фильма с коробкой стал одним из самых обсуждаемых и пародируемых поворотов в истории триллеров.","wiki_en":"Seven (1995 film)"},{"name":"Зелёная миля","emoji":"🐭","meta":["драма","1999","Фрэнк Дарабонт"],"description":"Надзиратель блока смертников в тюрьме 1930-х годов сталкивается с осуждённым великаном, обладающим необъяснимым даром исцеления. Экранизация романа Стивена Кинга сочетает тюремную драму с элементами мистики и размышлениями о вере и справедливости.","fact":"Роман Стивена Кинга, положенный в основу фильма, изначально выходил отдельными выпусками, как сериал в мягкой обложке.","wiki_en":"The Green Mile (film)"},{"name":"Список Шиндлера","emoji":"🕯️","meta":["историческая драма","1993","Стивен Спилберг"],"description":"Немецкий предприниматель Оскар Шиндлер во время Второй мировой войны спасает жизни более тысячи польских евреев, нанимая их на работу на свою фабрику. Снятый почти полностью в чёрно-белой гамме фильм Спилберга основан на реальной истории.","fact":"Спилберг отказался от гонорара за этот фильм, а на доходы от него основал фонд, записывающий свидетельства переживших Холокост.","wiki_en":"Schindler's List"},{"name":"Спасти рядового Райана","emoji":"🪖","meta":["военная драма","1998","Стивен Спилберг"],"description":"Отряд американских солдат получает приказ найти и вернуть домой единственного выжившего из четырёх братьев после высадки в Нормандии. Открывающая фильм долгая сцена штурма пляжа считается одной из самых реалистичных батальных сцен в истории кино.","fact":"Из-за предельно жёсткого изображения боя некоторые ветераны Второй мировой войны, по свидетельствам, покидали кинозал во время просмотра.","wiki_en":"Saving Private Ryan"},{"name":"Гладиатор","emoji":"⚔️","meta":["историческая драма","2000","Ридли Скотт"],"description":"Римский полководец, преданный завистливым наследником императора, лишается семьи и свободы и оказывается на арене гладиатором, вынашивая план мести. Фильм Ридли Скотта возродил интерес к жанру пеплума и античным сюжетам в голливудском кино.","fact":"Фраза героя «Меня зовут Максимус Децим Меридий» стала одной из самых узнаваемых реплик-представлений в кино.","wiki_en":"Gladiator (2000 film)"},{"name":"Храброе сердце","emoji":"🗡️","meta":["историческая драма","1995","Мел Гибсон"],"description":"Шотландец Уильям Уоллес поднимает восстание против английского владычества после того, как английские солдаты убивают его жену. Масштабная историческая драма с батальными сценами принесла Мелу Гибсону «Оскар» за режиссуру.","fact":"Клетчатый рисунок килтов в фильме исторически не соответствует эпохе — тартаны в таком виде появились значительно позже показанных событий.","wiki_en":"Braveheart"},{"name":"Леон","emoji":"🌱","meta":["криминальная драма","1994","Люк Бессон"],"description":"Профессиональный убийца-одиночка берёт под опеку двенадцатилетнюю девочку, чью семью убили коррумпированные агенты, и невольно привязывается к ней. Фильм Люка Бессона сочетает жёсткий боевик с неожиданно трогательной историей о дружбе и защите.","fact":"Комнатное растение, которое герой всюду носит с собой и о котором заботится как о единственном друге, стало символом всего фильма.","wiki_en":"Léon: The Professional"},{"name":"Пятый элемент","emoji":"🚕","meta":["фантастика","1997","Люк Бессон"],"description":"Таксист в футуристическом Нью-Йорке XXIII века неожиданно оказывается втянут в спасение мира вместе с загадочной девушкой, воплощающей древнее оружие против абсолютного зла. Яркий визуальный стиль Люка Бессона соединил комикс-эстетику с масштабной космической фантастикой.","fact":"Костюмы для фильма разработал модельер Жан-Поль Готье, включая знаменитый наряд из бинтов у героини Милы Йовович.","wiki_en":"The Fifth Element"},{"name":"Король Лев","emoji":"🦁","meta":["мультфильм","1994","Роджер Аллерс, Роб Минкофф"],"description":"Львёнок Симба должен унаследовать трон отца в африканской саванне, но после трагедии, в которой винит себя, бежит из родного прайда и годы спустя возвращается, чтобы занять законное место. Мультфильм Disney с музыкой Элтона Джона стал одним из самых кассовых анимационных фильмов своего времени.","fact":"Сюжет мультфильма во многом перекликается с шекспировским «Гамлетом» — с мотивами предательства и мести за отца.","wiki_en":"The Lion King"},{"name":"История игрушек","emoji":"🧸","meta":["мультфильм","1995","Джон Лассетер"],"description":"Ковбой Вуди, любимая игрушка мальчика Энди, ревниво воспринимает появление нового яркого космического рейнджера Базза Лайтера и постепенно учится делить внимание хозяина. Фильм студии Pixar стал первым полнометражным мультфильмом, полностью созданным на компьютере.","fact":"Рендер отдельных кадров первого полностью компьютерного мультфильма занимал часы на тогдашних компьютерах.","wiki_en":"Toy Story"},{"name":"Шрек","emoji":"🧅","meta":["мультфильм","2001","Эндрю Адамсон, Вики Дженсон"],"description":"Угрюмый зелёный людоед, желающий вернуть уединение на своём болоте, соглашается спасти принцессу из башни, охраняемой драконом, в обмен на возвращение земель. Мультфильм пародирует классические сказочные сюжеты и сочетает добрый юмор с ироничными отсылками для взрослых.","fact":"Фраза Шрека о том, что у людоедов, как у луковиц, есть слои, стала одной из самых цитируемых в мультфильме.","wiki_en":"Shrek"},{"name":"В поисках Немо","emoji":"🐠","meta":["мультфильм","2003","Эндрю Стэнтон"],"description":"Рыба-клоун по имени Марлин отправляется через весь океан на поиски похищенного аквариумистами сына Немо, преодолевая опасности вместе с рассеянной, но доброй спутницей Дори. Мультфильм Pixar прославился реалистичной анимацией подводного мира.","fact":"После выхода мультфильма резко вырос спрос на рыб-клоунов для домашних аквариумов, что обеспокоило защитников природы.","wiki_en":"Finding Nemo"},{"name":"ВАЛЛ-И","emoji":"🤖","meta":["мультфильм","2008","Эндрю Стэнтон"],"description":"На опустевшей от мусора Земле остаётся работать одинокий робот-уборщик, который влюбляется в прилетевшего с разведывательной миссией робота нового поколения. Первая треть мультфильма почти лишена диалогов, но полна выразительной пантомимы.","fact":"Голос и звуки ВАЛЛ-И придумал звукорежиссёр Бен Бёртт — тот же человек, что когда-то создал «речь» робота R2-D2.","wiki_en":"WALL-E"},{"name":"Вверх","emoji":"🎈","meta":["мультфильм","2009","Пит Доктер"],"description":"Пожилой вдовец прикрепляет к своему дому тысячи воздушных шаров и отправляется в путешествие в Южную Америку, о котором мечтал с женой, а по пути обнаруживает на борту юного бойскаута. Мультфильм Pixar известен пронзительным вступлением о целой совместной жизни без единого слова.","fact":"Помимо награды за анимацию, мультфильм получил редкую для жанра номинацию на «Оскар» за лучший фильм года.","wiki_en":"Up (2009 film)"},{"name":"Холодное сердце","emoji":"❄️","meta":["мультфильм","2013","Крис Бак, Дженнифер Ли"],"description":"Принцесса с даром замораживать всё вокруг случайно погружает родное королевство в вечную зиму и скрывается в горах, а её сестра отправляется на поиски, чтобы всё исправить. Мультфильм Disney сделал главной темой не романтическую любовь, а связь между сёстрами.","fact":"Песня Let It Go из мультфильма стала мировым хитом и была записана на десятках языков.","wiki_en":"Frozen (2013 film)"},{"name":"Унесённые призраками","emoji":"🐉","meta":["мультфильм","2001","Хаяо Миядзаки"],"description":"Девочка по дороге на новое место жительства с родителями попадает в мир духов, где её родителей превращают в свиней, и ей приходится устроиться на работу в волшебные бани, чтобы спасти семью. Мультфильм Хаяо Миядзаки стал первым аниме, получившим «Оскар».","fact":"Фильм долгое время оставался самым кассовым в истории японского кинопроката.","wiki_en":"Spirited Away"},{"name":"Пираты Карибского моря: Проклятие Чёрной жемчужины","emoji":"🏴‍☠️","meta":["приключения","2003","Гор Вербински"],"description":"Кузнец отправляется спасать похищенную дочь губернатора вместе с эксцентричным пиратом Джеком Воробьём, чей корабль проклят, а команда обращается в скелетов при лунном свете. Фильм по мотивам аттракциона Disneyland неожиданно возродил жанр пиратских приключений.","fact":"Роль Джека Воробья Джонни Депп во многом построил на манерах музыканта Кита Ричардса.","wiki_en":"Pirates of the Caribbean: The Curse of the Black Pearl"},{"name":"Человек-паук","emoji":"🕷️","meta":["супергеройский фильм","2002","Сэм Рэйми"],"description":"Обычный школьник Питер Паркер после укуса радиоактивного паука обретает сверхспособности и, после гибели дяди, решает использовать их во благо города. Фильм Сэма Рэйми стал одним из первых по-настоящему кассовых супергеройских блокбастеров XXI века.","fact":"Фраза дяди Бена «с большой силой приходит и большая ответственность» стала девизом персонажа на десятилетия вперёд.","wiki_en":"Spider-Man (2002 film)"},{"name":"Железный человек","emoji":"🦾","meta":["супергеройский фильм","2008","Джон Фавро"],"description":"Миллиардер и оружейный магнат, попавший в плен, строит бронированный костюм, чтобы выбраться, а вернувшись домой, продолжает совершенствовать его для борьбы со злом. Фильм положил начало кинематографической вселенной Marvel.","fact":"Сцена после титров с появлением Ника Фьюри задала традицию пост-титровых эпизодов, связывающих фильмы Marvel в одну вселенную.","wiki_en":"Iron Man (film)"},{"name":"Мстители","emoji":"🛡️","meta":["супергеройский фильм","2012","Джосс Уидон"],"description":"Отряд самых сильных героев Земли — Железный человек, Тор, Капитан Америка, Халк и другие — впервые объединяется, чтобы остановить вторжение инопланетной армии на Нью-Йорк. Фильм стал первым масштабным кроссовером кинематографической вселенной Marvel.","fact":"Собрать всех героев из отдельных франшиз в одном фильме до этого в таком масштабе в кино почти не пробовали.","wiki_en":"The Avengers (2012 film)"},{"name":"Мстители: Финал","emoji":"💎","meta":["супергеройский фильм","2019","Энтони Руссо, Джо Руссо"],"description":"После катастрофических событий предыдущего фильма оставшиеся супергерои ищут способ обратить вспять уничтожение половины всего живого во вселенной. Финал многолетней саги Marvel стал одним из самых кассовых фильмов в истории кино.","fact":"Фильм на некоторое время стал самым кассовым в мировой истории кинопроката, обойдя «Аватар».","wiki_en":"Avengers: Endgame"},{"name":"Джокер","emoji":"🃏","meta":["драма","2019","Тодд Филлипс"],"description":"Неудачливый клоун и начинающий комик, страдающий психическим расстройством, постепенно теряет связь с реальностью на фоне равнодушия и жестокости окружающего его Готэма. Фильм переосмыслил происхождение классического злодея как мрачную социальную драму.","fact":"Хоакин Феникс сбросил значительный вес ради роли, чтобы придать герою измождённый, надломленный вид.","wiki_en":"Joker (2019 film)"},{"name":"Дэдпул","emoji":"🗡️","meta":["супергеройская комедия","2016","Тим Миллер"],"description":"Бывший спецназовец, ставший подопытным в подпольном эксперименте по исцелению от рака, обретает сверхспособности вместе с обезображенной внешностью и мстит под маской болтливого наёмника. Фильм выделяется ломанием четвёртой стены и чёрным юмором, нетипичным для жанра.","fact":"Райан Рейнольдс годами добивался съёмок фильма, и решающую роль сыграл утёкший в сеть тестовый ролик, который восторженно приняли зрители.","wiki_en":"Deadpool (film)"},{"name":"Стражи Галактики","emoji":"🌌","meta":["супергеройский фильм","2014","Джеймс Ганн"],"description":"Разношёрстная банда космических изгоев — включая говорящего енота и человекоподобное дерево — случайно оказывается втянута в схватку за могущественный артефакт, способный уничтожить целые планеты. Фильм выделялся ретро-саундтреком из хитов 1970-х.","fact":"Плейлист Awesome Mix с ретро-хитами, который слушает главный герой, стал самостоятельным хитом на музыкальных сервисах.","wiki_en":"Guardians of the Galaxy (film)"},{"name":"Безумный Макс: Дорога ярости","emoji":"🏜️","meta":["боевик","2015","Джордж Миллер"],"description":"В выжженной пустоши постапокалиптического будущего беглянка-военачальница Фуриоса вместе со случайным попутчиком Максом пытается вырваться от тирана-деспота на гружённом женщинами грузовике. Почти двухчасовая автомобильная погоня принесла фильму широкое признание критиков.","fact":"Большинство трюков и автомобильных каскадов в фильме сняты практически без компьютерной графики.","wiki_en":"Mad Max: Fury Road"},{"name":"Джон Уик","emoji":"🐶","meta":["боевик","2014","Чад Стахелски"],"description":"Отошедший от дел наёмный убийца возвращается к прежнему ремеслу после того, как бывшие сообщники убивают подаренного покойной женой щенка и угоняют его машину. Фильм известен изобретательной хореографией перестрелок и рукопашного боя, задавшей новый стандарт жанра.","fact":"Постановкой боевых сцен занимались бывшие каскадёры, что придало перестрелкам необычную для Голливуда физическую достоверность.","wiki_en":"John Wick"},{"name":"Убить Билла","emoji":"🟡","meta":["боевик","2003","Квентин Тарантино"],"description":"Бывшая наёмная убийца, выжившая после расстрела на собственной свадьбе, составляет список бывших коллег из «Смертельной гадюки» и мстит им одному за другим. Фильм Тарантино соединяет эстетику японских самурайских лент, гонконгских боевиков и спагетти-вестернов.","fact":"Жёлтый спортивный костюм героини — прямая отсылка к экипировке Брюса Ли в фильме «Игра смерти».","wiki_en":"Kill Bill: Volume 1"},{"name":"Джанго освобождённый","emoji":"⛓️","meta":["вестерн","2012","Квентин Тарантино"],"description":"Освобождённый раб объединяется с немецким охотником за головами, чтобы найти и спасти жену, оставшуюся в рабстве у жестокого плантатора на юге США. Тарантино переосмысляет жанр спагетти-вестерна через призму темы рабства в довоенной Америке.","fact":"Название и часть музыкальной темы фильма отсылают к итальянскому вестерну 1966 года «Джанго».","wiki_en":"Django Unchained"},{"name":"Бесславные ублюдки","emoji":"🎬","meta":["военная драма","2009","Квентин Тарантино"],"description":"Отряд американских солдат-евреев охотится за нацистскими офицерами во Франции времён Второй мировой войны, а параллельно хозяйка парижского кинотеатра готовит собственную месть за убитую семью. Тарантино соединяет альтернативную историю с данью уважения кино.","fact":"Название фильма содержит намеренную орфографическую ошибку, оставленную без объяснений.","wiki_en":"Inglourious Basterds"},{"name":"Однажды в… Голливуде","emoji":"📺","meta":["трагикомедия","2019","Квентин Тарантино"],"description":"Стареющий актёр телевизионных вестернов и его каскадёр-дублёр пытаются удержаться на плаву в стремительно меняющемся Голливуде конца 1960-х, по соседству с домом Шэрон Тейт. Фильм Тарантино воссоздаёт атмосферу Лос-Анджелеса той эпохи.","fact":"Действие фильма разворачивается в Лос-Анджелесе 1969 года и отсылает к реальным трагическим событиям того времени.","wiki_en":"Once Upon a Time in Hollywood"},{"name":"Волк с Уолл-стрит","emoji":"💰","meta":["биографическая комедия","2013","Мартин Скорсезе"],"description":"Биржевой брокер Джордан Белфорт строит финансовую империю на мошеннических схемах и стремительно скатывается в мир немыслимой роскоши, наркотиков и вседозволенности. Фильм основан на реальных мемуарах и известен энергичным темпом и провокационным юмором.","fact":"Леонардо Ди Каприо сыграл в фильме реального человека, Джордана Белфорта, который позже появляется в эпизодической роли в самой картине.","wiki_en":"The Wolf of Wall Street (2013 film)"},{"name":"Остров проклятых","emoji":"🏝️","meta":["психологический триллер","2010","Мартин Скорсезе"],"description":"Федеральный маршал расследует таинственное исчезновение пациентки из психиатрической лечебницы на удалённом острове, но чем дальше продвигается расследование, тем менее надёжной кажется реальность вокруг него. Экранизация романа Денниса Лихейна выстроена как атмосферный триллер.","fact":"Мартин Скорсезе намеренно насыщал фильм визуальными и сюжетными подсказками, которые становятся понятны только при повторном просмотре.","wiki_en":"Shutter Island"},{"name":"Отступники","emoji":"🕵️","meta":["криминальная драма","2006","Мартин Скорсезе"],"description":"Полицейский под прикрытием внедряется в ирландскую мафию Бостона, в то время как человек мафии одновременно работает кротом внутри самой полиции, и оба пытаются вычислить друг друга. Фильм принёс Мартину Скорсезе первый в карьере «Оскар» за режиссуру.","fact":"Сюжет фильма — ремейк гонконгского триллера «Двойная рокировка».","wiki_en":"The Departed"},{"name":"Славные парни","emoji":"🔫","meta":["криминальная драма","1990","Мартин Скорсезе"],"description":"История восхождения и падения мелкого гангстера, который с юности мечтал стать частью итало-американской мафии Нью-Йорка и постепенно проходит путь от мелких краж до крупных преступлений. Фильм основан на реальной биографии и известен стремительным монтажом.","fact":"Знаменитый длинный непрерывный кадр прохода через кухню ресторана в фильме снят одним дублем без видимых склеек.","wiki_en":"Goodfellas"},{"name":"Таксист","emoji":"🚕","meta":["психологическая драма","1976","Мартин Скорсезе"],"description":"Одинокий ветеран войны во Вьетнаме подрабатывает ночным таксистом в криминальном Нью-Йорке и, всё больше отчуждаясь от общества, вынашивает план насильственного очищения города. Фильм стал одним из главных портретов городского одиночества в американском кино.","fact":"Музыку к фильму написал Бернард Херрманн, многолетний соавтор Хичкока, — это была его последняя работа в кино, и картина посвящена его памяти.","wiki_en":"Taxi Driver"},{"name":"Лицо со шрамом","emoji":"🌎","meta":["криминальная драма","1983","Брайан Де Пальма"],"description":"Кубинский эмигрант Тони Монтана прибывает в Майами без денег и постепенно выстраивает наркоимперию, поднимаясь по кровавой лестнице криминального мира. Ремейк фильма 1932 года стал культовой историей об американской мечте, вывернутой наизнанку.","fact":"Надпись «Мир принадлежит тебе», которую герой видит в небе на пролетающем дирижабле, стала девизом всей истории.","wiki_en":"Scarface (1983 film)"},{"name":"Большой Лебовски","emoji":"🎳","meta":["комедия","1998","Итан Коэн, Джоэл Коэн"],"description":"Ленивого любителя боулинга по прозвищу Чувак по ошибке принимают за миллионера с тем же именем, втягивая в нелепую историю с похищением и выкупом. Эксцентричная комедия братьев Коэн поначалу прошла незамеченной, но со временем обрела огромный культовый фандом.","fact":"Поклонники фильма ежегодно устраивают посвящённые ему фестивали Lebowski Fest с боулингом и костюмами героев.","wiki_en":"The Big Lebowski"},{"name":"Старикам тут не место","emoji":"🪙","meta":["триллер","2007","Итан Коэн, Джоэл Коэн"],"description":"Случайно наткнувшийся на деньги с места неудавшейся наркосделки охотник пытается скрыться от безжалостного убийцы, преследующего его по пустошам Техаса. Экранизация романа Кормака Маккарти принесла братьям Коэн «Оскар» за лучший фильм.","fact":"Главное оружие убийцы в фильме — пневматический пистолет для забоя скота, совершенно необычный выбор для криминального триллера.","wiki_en":"No Country for Old Men"},{"name":"Красота по-американски","emoji":"🌹","meta":["драма","1999","Сэм Мендес"],"description":"Разочарованный в жизни и браке мужчина среднего возраста переживает кризис, влюбляется в подругу дочери и решает радикально изменить свою жизнь наперекор пригородным условностям. Фильм известен визуальной символикой, в частности образом рассыпанных лепестков роз.","fact":"Летящий по ветру полиэтиленовый пакет в одной из сцен стал одним из самых обсуждаемых и пародируемых символов фильма.","wiki_en":"American Beauty (1999 film)"},{"name":"Шестое чувство","emoji":"👦","meta":["мистический триллер","1999","М. Найт Шьямалан"],"description":"Детский психолог пытается помочь мальчику, который утверждает, что видит мёртвых людей, и постепенно оба сталкиваются с истиной, меняющей всё понимание истории. Фильм прославился одним из самых неожиданных финальных твистов в истории кино.","fact":"Фраза мальчика «Я вижу мёртвых людей» стала одной из самых узнаваемых и часто пародируемых реплик в кино.","wiki_en":"The Sixth Sense"},{"name":"Игры разума","emoji":"🧮","meta":["биографическая драма","2001","Рон Ховард"],"description":"Талантливый математик Джон Нэш добивается прорывных научных результатов, одновременно борясь с прогрессирующей шизофренией, которая искажает его восприятие реальности. Фильм основан на биографии реального нобелевского лауреата по экономике.","fact":"Картина получила «Оскар» за лучший фильм года, а Дженнифер Коннелли — за лучшую женскую роль второго плана.","wiki_en":"A Beautiful Mind (film)"},{"name":"Поймай меня, если сможешь","emoji":"✈️","meta":["криминальная комедия","2002","Стивен Спилберг"],"description":"Подросток становится виртуозным мошенником, выдающим себя за пилота, врача и юриста и подделывающим чеки на миллионы долларов, пока за ним не начинает охоту упорный агент ФБР. Фильм основан на автобиографии реального афериста Фрэнка Абигнейла.","fact":"Реальный Фрэнк Абигнейл, чья история легла в основу сюжета, позже стал консультантом по банковской безопасности.","wiki_en":"Catch Me If You Can"},{"name":"Одиннадцать друзей Оушена","emoji":"🎰","meta":["криминальная комедия","2001","Стивен Содерберг"],"description":"Профессиональный аферист Дэнни Оушен собирает команду из одиннадцати специалистов, чтобы провернуть дерзкое ограбление сразу трёх казино Лас-Вегаса в одну ночь. Ремейк фильма 1960 года со звёздным составом стал эталоном лёгкого стильного кино об ограблениях.","fact":"Сцена с фонтанами отеля Bellagio, на фоне которых молча стоят герои в финале, стала одним из самых узнаваемых кадров фильма.","wiki_en":"Ocean's Eleven (2001 film)"},{"name":"Миссия невыполнима","emoji":"🕶️","meta":["боевик","1996","Брайан Де Пальма"],"description":"Агента спецслужбы подставляют после провала миссии, в результате которой погибает вся его команда, и он вынужден в одиночку выяснять, кто предатель, оставаясь вне закона. Фильм по мотивам культового телесериала 1960-х положил начало долгоживущей экшен-франшизе Тома Круза.","fact":"Сцена проникновения в защищённое хранилище ЦРУ, где герой спускается на тросе почти касаясь пола, стала одной из самых пародируемых в кино.","wiki_en":"Mission: Impossible (film)"},{"name":"Казино «Рояль»","emoji":"🎲","meta":["шпионский боевик","2006","Мартин Кэмпбелл"],"description":"Новичок в статусе агента 007 Джеймс Бонд получает первое серьёзное задание — обыграть в покер финансиста террористов за карточным столом в казино в Черногории. Фильм перезапустил франшизу о Бонде с более жёстким и приземлённым тоном.","fact":"Это был первый фильм о Бонде с Дэниэлом Крейгом, который поначалу вызвал скепсис у части фанатов, но позже завоевал признание.","wiki_en":"Casino Royale (2006 film)"},{"name":"Рокки","emoji":"🥊","meta":["спортивная драма","1976","Джон Эвилдсен"],"description":"Малоизвестный боксёр из рабочего района Филадельфии неожиданно получает шанс сразиться с чемпионом мира в титульном бою и использует его, чтобы доказать себе и другим, что способен пройти дистанцию. Малобюджетный фильм со Сталлоне стал одной из главных историй об упорстве в кино.","fact":"Пробежка героя по ступеням Филадельфийского художественного музея превратилась в туристическую достопримечательность, известную как «ступени Рокки».","wiki_en":"Rocky"},{"name":"Рэмбо: Первая кровь","emoji":"🔪","meta":["боевик","1982","Тед Котчефф"],"description":"Ветеран войны во Вьетнаме, столкнувшись с несправедливым преследованием со стороны полиции маленького городка, скрывается в лесу и в одиночку противостоит целому отряду. Фильм поднимает тему непростого возвращения ветеранов к мирной жизни и представляет публике героя Рэмбо.","fact":"В отличие от кровопролитных сиквелов, в первом фильме герой почти не убивает — он в основном обезвреживает и запугивает преследователей.","wiki_en":"First Blood"},{"name":"Хищник","emoji":"👽","meta":["фантастический боевик","1987","Джон Мактирнан"],"description":"Отряд элитных спецназовцев отправляется на спасательную операцию в центральноамериканские джунгли и один за другим становится добычей невидимого инопланетного охотника. Фильм соединил военный боевик с фантастикой ужасов и подарил жанру одного из самых узнаваемых монстров.","fact":"Костюм Хищника изначально создавался для другого актёра и облика, но был полностью переделан незадолго до съёмок по настоянию создателей.","wiki_en":"Predator (film)"},{"name":"Робокоп","emoji":"🦾","meta":["фантастический боевик","1987","Пол Верховен"],"description":"Тяжело раненный при исполнении полицейский Детройта возвращается на службу в виде киборга с почти утраченной человеческой памятью и постепенно вспоминает, кем он был. Фильм Пола Верховена соединяет жёсткий боевик с острой сатирой на корпорации и медиа.","fact":"Из-за чрезмерной жестокости фильм пришлось несколько раз перемонтировать, чтобы получить в США прокатный рейтинг вместо запретительного.","wiki_en":"RoboCop"},{"name":"Охотники за привидениями","emoji":"👻","meta":["фантастическая комедия","1984","Айван Райтман"],"description":"Трое незадачливых учёных-парапсихологов открывают в Нью-Йорке частную службу по отлову призраков и неожиданно сталкиваются с настоящим сверхъестественным нашествием. Фильм соединил комедию с фантастикой о привидениях и стал культовой классикой 1980-х.","fact":"Песня Ghostbusters Рэя Паркера-младшего из этого фильма поднялась на первое место американского чарта синглов.","wiki_en":"Ghostbusters (1984 film)"},{"name":"Люди в чёрном","emoji":"🕶️","meta":["фантастическая комедия","1997","Барри Зонненфельд"],"description":"Секретное агентство в строгих чёрных костюмах тайно следит за инопланетянами, живущими среди людей на Земле, и новобранец вместе с опытным напарником берётся за расследование опасного дела. Фильм по мотивам комикса сочетает экшен, юмор и изобретательный дизайн пришельцев.","fact":"Устройство-вспышка, стирающее память свидетелям в фильме, стало одним из узнаваемых атрибутов поп-культуры — нейрализатор.","wiki_en":"Men in Black (film)"},{"name":"День сурка","emoji":"🔁","meta":["комедия","1993","Гарольд Рэмис"],"description":"Циничный телеведущий-метеоролог застревает во временной петле и снова и снова проживает один и тот же день в маленьком городке, пока не меняется как личность. Фильм подарил массовой культуре само выражение «день сурка» для обозначения бесконечного повторения.","fact":"Точное число повторяющихся дней в фильме никогда не называется, но по подсчётам поклонников оно могло составлять годы.","wiki_en":"Groundhog Day (film)"},{"name":"Маска","emoji":"🎭","meta":["фантастическая комедия","1994","Чак Расселл"],"description":"Скромный банковский служащий находит древнюю маску, надев которую превращается в безумного зеленолицего персонажа с суперспособностями и раскованным характером. Фильм прославил Джима Керри как звезду эксцентричной физической комедии и активно использовал компьютерную графику для трансформаций героя.","fact":"Комикс, по которому снят фильм, изначально был куда мрачнее и жёстче итоговой комедийной экранизации.","wiki_en":"The Mask (film)"},{"name":"Тупой и ещё тупее","emoji":"🚐","meta":["комедия","1994","Питер Фаррелли"],"description":"Два наивных и недалёких приятеля отправляются через всю страну, чтобы вернуть забытый чемодан с деньгами симпатичной девушке, даже не подозревая, что внутри выкуп для похитителей. Абсурдная комедия с Джимом Керри и Джеффом Дэниелсом стала классикой жанра «глупых» комедий 1990-х.","fact":"Фургон героев, оформленный под лохматую собаку, стал одним из самых узнаваемых автомобилей в истории кинокомедий.","wiki_en":"Dumb and Dumber"},{"name":"Мальчишник в Вегасе","emoji":"🐯","meta":["комедия","2009","Тодд Филлипс"],"description":"Трое друзей просыпаются в номере отеля в Лас-Вегасе после дикой ночи перед свадьбой, не помня ничего из произошедшего, а жених и вовсе бесследно исчез. Комедия строится вокруг попыток героев по обрывочным уликам восстановить события прошлой ночи.","fact":"Фильм стал одной из самых кассовых комедий с рейтингом R за всю историю проката.","wiki_en":"The Hangover"},{"name":"Американский пирог","emoji":"🥧","meta":["подростковая комедия","1999","Пол Уайц"],"description":"Четверо старшеклассников заключают пакт лишиться девственности до выпускного бала и переживают из-за этого серию неловких и комичных ситуаций. Фильм стал одной из самых узнаваемых подростковых комедий рубежа веков и дал начало целой киносерии.","fact":"Снятая с очень скромным бюджетом комедия неожиданно собрала в мировом прокате больше двухсот миллионов долларов.","wiki_en":"American Pie (film)"},{"name":"Дьявол носит Prada","emoji":"👜","meta":["комедийная драма","2006","Дэвид Фрэнкел"],"description":"Выпускница журфака устраивается ассистенткой к деспотичной и требовательной главной редакторше модного журнала и постепенно теряет себя в погоне за успехом в мире высокой моды. Экранизация романа Лорен Вайсбергер во многом основана на реальном опыте работы автора в индустрии моды.","fact":"Прообразом властной героини фильма считается реальная легендарная главред американского Vogue Анна Винтур.","wiki_en":"The Devil Wears Prada (film)"},{"name":"Ла-Ла Ленд","emoji":"🎹","meta":["мюзикл","2016","Дэмьен Шазелл"],"description":"Начинающая актриса и джазовый пианист влюбляются друг в друга в современном Лос-Анджелесе, пытаясь при этом не потерять собственные творческие амбиции. Мюзикл отдаёт дань голливудской классике жанра и известен ярким использованием цвета и танцевальными номерами.","fact":"На церемонии «Оскара» фильм по ошибке на несколько минут объявили победителем в номинации «Лучший фильм» вместо настоящего лауреата.","wiki_en":"La La Land (film)"},{"name":"Одержимость","emoji":"🥁","meta":["драма","2014","Дэмьен Шазелл"],"description":"Амбициозный молодой барабанщик консерватории попадает в класс к жестокому и требовательному дирижёру, готовому унижать студентов ради стремления к музыкальному совершенству. Фильм исследует цену одержимости мастерством и построен на напряжённом противостоянии учителя и ученика.","fact":"За роль деспотичного наставника Дж. К. Симмонс получил «Оскар» за лучшую мужскую роль второго плана.","wiki_en":"Whiplash (2014 film)"},{"name":"Паразиты","emoji":"🪨","meta":["социальный триллер","2019","Пон Джун Хо"],"description":"Бедная семья из полуподвальной квартиры Сеула постепенно и хитроумно внедряется в дом состоятельного семейства, устраиваясь туда на работу под чужими личинами. Южнокорейский фильм соединяет чёрную комедию с острой социальной драмой о неравенстве.","fact":"Фильм стал первым неанглоязычным лауреатом «Оскара» за лучший фильм в истории премии.","wiki_en":"Parasite (2019 film)"},{"name":"Оппенгеймер","emoji":"☢️","meta":["биографическая драма","2023","Кристофер Нолан"],"description":"Физик Роберт Оппенгеймер возглавляет секретный Манхэттенский проект по созданию первой атомной бомбы, а после войны сталкивается с политическими последствиями и моральной тяжестью своего изобретения. Фильм Кристофера Нолана снят в основном на плёнку.","fact":"Взрыв атомной бомбы для сцены испытания «Тринити» был воссоздан практическими эффектами без использования компьютерной графики.","wiki_en":"Oppenheimer (film)"},{"name":"Барби","emoji":"💗","meta":["комедия","2023","Грета Гервиг"],"description":"Классическая кукла Барби из идеального розового мира неожиданно начинает задумываться о смерти и несовершенстве и вместе с Кеном отправляется в реальный мир, чтобы разобраться в себе. Фильм соединяет яркую комедию с ироничным разговором о наследии самой известной куклы в истории.","fact":"Из-за масштабных закупок розовой краски для декораций съёмочная группа якобы временно вызвала её дефицит на рынке.","wiki_en":"Barbie (film)"},{"name":"Дюна","emoji":"🏜️","meta":["фантастика","2021","Дени Вильнёв"],"description":"Наследник благородного дома принимает управление пустынной планетой Арракис, единственным источником ценнейшего во вселенной вещества, и оказывается втянут в смертельные политические интриги. Экранизация романа Фрэнка Герберта известна масштабной постановкой пустынного мира и песчаных червей.","fact":"Роман Фрэнка Герберта, легший в основу фильма, десятилетиями считался «непроходимым» для экранизации из-за сложности мира.","wiki_en":"Dune (2021 film)"},{"name":"Топ Ган: Мэверик","emoji":"✈️","meta":["боевик","2022","Джозеф Косински"],"description":"Ветеран-лётчик Мэверик возвращается инструктором в элитную школу пилотов, чтобы подготовить новое поколение к почти невыполнимой боевой миссии. Спустя десятилетия после оригинала сиквел прославился реальными съёмками воздушных манёвров, а не компьютерной графикой.","fact":"Актёры проходили лётную подготовку и снимались в настоящих реактивных самолётах во время манёвров с реальными перегрузками.","wiki_en":"Top Gun: Maverick"},{"name":"Голодные игры","emoji":"🏹","meta":["фантастический боевик","2012","Гэри Росс"],"description":"В антиутопическом будущем подростков из бедных округов ежегодно отправляют на смертельное телешоу-соревнование, и девушка вызывается добровольцем вместо младшей сестры. Экранизация романа Сьюзен Коллинз стала одной из главных подростковых франшиз своего времени.","fact":"Приветственный жест из трёх пальцев, пришедший из книг, позже стали использовать как символ протеста в разных странах.","wiki_en":"The Hunger Games (film)"},{"name":"Сумерки","emoji":"🧛","meta":["фэнтезийная мелодрама","2008","Кэтрин Хардвик"],"description":"Обычная старшеклассница переезжает в маленький дождливый городок и влюбляется в загадочного одноклассника, который оказывается вампиром, борющимся с собственной природой. Экранизация романа Стефани Майер породила одну из самых заметных подростковых франшиз о вампирах.","fact":"Небольшой городок Форкс в штате Вашингтон, где происходит действие, после выхода фильма превратился в место паломничества поклонников.","wiki_en":"Twilight (2008 film)"},{"name":"1+1","emoji":"🤝","meta":["комедийная драма","2011","Оливье Накаш, Эрик Толедано"],"description":"Богатый аристократ, парализованный после несчастного случая, нанимает в помощники молодого парня из бедного пригорода без опыта, и между непохожими друг на друга людьми возникает крепкая дружба. Французский фильм основан на реальной истории и стал одним из самых кассовых французских фильмов в мире.","fact":"В основу сюжета легла реальная история дружбы предпринимателя Филиппа Поццо ди Борго и его помощника.","wiki_en":"The Intouchables"},{"name":"Амели","emoji":"🎨","meta":["романтическая комедия","2001","Жан-Пьер Жёне"],"description":"Застенчивая официантка парижского кафе решает тайно и изобретательно вмешиваться в жизни окружающих, устраивая маленькие добрые чудеса, оставаясь при этом в тени сама. Фильм известен яркой стилизованной картинкой Парижа и стал визитной карточкой французского кино рубежа веков.","fact":"Многие сцены фильма снимались в реальном парижском кафе на Монмартре, которое после премьеры стало туристической достопримечательностью.","wiki_en":"Amélie"},{"name":"Жизнь прекрасна","emoji":"🎪","meta":["трагикомедия","1997","Роберто Бениньи"],"description":"Еврейский отец в оккупированной нацистами Италии, оказавшись вместе с маленьким сыном в концлагере, превращает происходящий кошмар в придуманную для ребёнка игру, чтобы уберечь его психику. Итальянский фильм соединяет комедию и трагедию Холокоста, что стало предметом споров критиков.","fact":"Роберто Бениньи выступил режиссёром, соавтором сценария и исполнителем главной роли, за которую получил «Оскар».","wiki_en":"Life Is Beautiful"},{"name":"Хороший, плохой, злой","emoji":"🤠","meta":["вестерн","1966","Серджо Леоне"],"description":"Трое охотников за наживой — расчётливый стрелок, безжалостный наёмник и хитрый мошенник — идут по следу закопанного в безымянной могиле золота времён Гражданской войны в США. Итальянский вестерн Серджо Леоне с музыкой Эннио Морриконе завершает «долларовую трилогию».","fact":"Знаменитая финальная трёхсторонняя дуэль фильма снята с почти музыкальным монтажом крупных планов лиц и рук героев.","wiki_en":"The Good, the Bad and the Ugly"},{"name":"Психо","emoji":"🚿","meta":["психологический триллер","1960","Альфред Хичкок"],"description":"Молодая женщина, скрывающаяся после кражи крупной суммы денег, останавливается в уединённом придорожном мотеле, которым управляет странный молодой человек, живущий под гнётом властной матери. Фильм Хичкока перевернул представления о том, как строится напряжение в триллере.","fact":"Сцена убийства в душе, ставшая одной из самых знаменитых в истории кино, снималась несколько дней ради считаных секунд экранного времени.","wiki_en":"Psycho (1960 film)"},{"name":"Сияние","emoji":"🪓","meta":["психологические ужасы","1980","Стэнли Кубрик"],"description":"Писатель устраивается смотрителем уединённого горного отеля на зимний сезон вместе с семьёй, но постепенно поддаётся воздействию тёмной силы, обитающей в стенах здания. Экранизация романа Стивена Кинга стала одной из самых атмосферных и цитируемых картин в истории жанра ужасов.","fact":"Стивен Кинг, автор романа-первоисточника, долгое время был недоволен трактовкой Кубрика и считал её слишком холодной.","wiki_en":"The Shining (film)"},{"name":"2001 год: Космическая одиссея","emoji":"🪐","meta":["фантастика","1968","Стэнли Кубрик"],"description":"Загадочный чёрный монолит подталкивает развитие человечества от первобытных предков до полёта к Юпитеру, где экипаж космического корабля вступает в конфликт с взбунтовавшимся искусственным интеллектом. Фильм Кубрика известен почти медитативным темпом и новаторскими визуальными эффектами.","fact":"Многие спецэффекты фильма, снятые ещё до высадки человека на Луну, до сих пор выглядят убедительно без компьютерной графики.","wiki_en":"2001: A Space Odyssey (film)"},{"name":"Заводной апельсин","emoji":"👁️","meta":["антиутопия","1971","Стэнли Кубрик"],"description":"Юный предводитель уличной банды в антиутопическом Лондоне подвергается экспериментальному государственному лечению, призванному подавить в нём склонность к насилию. Экранизация романа Энтони Бёрджесса вызвала бурные споры из-за откровенного изображения жестокости.","fact":"После волны критики и подражательных актов насилия сам Кубрик добился прекращения проката фильма в Великобритании на много лет.","wiki_en":"A Clockwork Orange (film)"},{"name":"Касабланка","emoji":"🍸","meta":["мелодрама","1942","Майкл Кёртис"],"description":"Владелец бара в марокканской Касабланке, находящейся под властью коллаборационистского правительства Виши, вновь встречает бывшую возлюбленную, которая приезжает с мужем-участником Сопротивления в поисках спасения от нацистов. Фильм эпохи Второй мировой войны стал эталоном голливудской мелодрамы.","fact":"Фраза «Здесь начинается прекрасная дружба» и многие другие реплики фильма вошли в число самых цитируемых в истории кино.","wiki_en":"Casablanca (film)"},{"name":"Унесённые ветром","emoji":"🌾","meta":["историческая мелодрама","1939","Виктор Флеминг"],"description":"Своенравная дочь плантатора переживает Гражданскую войну в США и её последствия, отчаянно борясь за сохранение дома и добиваясь мужчин, которых не может получить. Масштабная экранизация романа Маргарет Митчелл долгое время оставалась самым кассовым фильмом в истории.","fact":"С учётом инфляции фильм по сей день считается одним из самых кассовых в истории кинопроката.","wiki_en":"Gone with the Wind (film)"},{"name":"Волшебник страны Оз","emoji":"🌈","meta":["мюзикл","1939","Виктор Флеминг"],"description":"Девочку из Канзаса вместе с домиком уносит ураганом в волшебную страну, где ей предстоит по дороге из жёлтого кирпича добраться до Изумрудного города, чтобы найти способ вернуться домой. Один из первых цветных голливудских блокбастеров стал классикой семейного кино.","fact":"Переход фильма от чёрно-белого Канзаса к цветной стране Оз стал одним из самых знаменитых визуальных приёмов в истории кино.","wiki_en":"The Wizard of Oz (1939 film)"},{"name":"Завтрак у Тиффани","emoji":"💎","meta":["романтическая комедия","1961","Блейк Эдвардс"],"description":"Эксцентричная светская девушка Холли Голайтли, живущая мечтами о роскоши и избегающая привязанностей, заводит дружбу с новым соседом по дому в Нью-Йорке. Экранизация повести Трумена Капоте сделала образ героини в чёрном платье и с длинным мундштуком одной из икон стиля XX века.","fact":"Чёрное платье героини от Живанши в одной из самых узнаваемых сцен фильма позже было продано на аукционе за рекордную сумму.","wiki_en":"Breakfast at Tiffany's (film)"},{"name":"Римские каникулы","emoji":"🛵","meta":["романтическая комедия","1953","Уильям Уайлер"],"description":"Уставшая от протокола европейская принцесса сбегает на одну ночь из-под опеки во время визита в Рим и, не раскрывая своего титула, проводит день с американским журналистом. Фильм принёс Одри Хепбёрн «Оскар» за первую большую роль в Голливуде и сделал Рим одной из главных романтических декораций в кино.","fact":"Поездка героев на мотороллере по Риму после выхода фильма резко повысила популярность вида транспорта Vespa.","wiki_en":"Roman Holiday"},{"name":"Пролетая над гнездом кукушки","emoji":"🏥","meta":["драма","1975","Милош Форман"],"description":"Мужчина, симулирующий психическое расстройство, чтобы избежать тюрьмы, попадает в психиатрическую больницу и постепенно восстаёт против деспотичных порядков, установленных суровой старшей медсестрой. Экранизация романа Кена Кизи стала одной из немногих картин, получивших все пять главных «Оскаров».","fact":"Съёмки проходили в настоящей психиатрической больнице в Орегоне, а её главный врач даже сыграл в фильме небольшую роль.","wiki_en":"One Flew Over the Cuckoo's Nest (film)"},{"name":"Апокалипсис сегодня","emoji":"🚁","meta":["военная драма","1979","Фрэнсис Форд Коппола"],"description":"Американский капитан получает секретное задание найти и ликвидировать одичавшего в джунглях полковника, создавшего собственный культ посреди войны во Вьетнаме. Съёмки фильма, вдохновлённого повестью Джозефа Конрада, сами превратились в изматывающую эпопею, растянувшуюся на годы.","fact":"Съёмки фильма настолько затянулись и вышли из-под контроля, что об этом позже сняли отдельный документальный фильм.","wiki_en":"Apocalypse Now"},{"name":"Семь самураев","emoji":"⚔️","meta":["приключенческая драма","1954","Акира Куросава"],"description":"Бедная японская деревня нанимает семерых странствующих самураев, чтобы защититься от регулярных набегов разбойников, и те учат крестьян обороне. Эпический фильм Акиры Куросавы оказал огромное влияние на мировое кино и лёг в основу вестерна «Великолепная семёрка».","fact":"На момент выхода это был один из самых дорогих и долгих в производстве фильмов в истории японского кино.","wiki_en":"Seven Samurai"},{"name":"Ирония судьбы, или С лёгким паром!","emoji":"🎄","meta":["новогодняя комедия","1975","Эльдар Рязанов"],"description":"Компания друзей в новогоднюю ночь по традиции ходит в баню, и подвыпившего героя по ошибке отправляют не на тот рейс, из-за чего он попадает в чужой город и чужую квартиру с одинаковым адресом. Советская новогодняя комедия десятилетиями остаётся неизменным атрибутом праздничного телевечера.","fact":"Песни в фильме звучат на стихи Цветаевой, Пастернака, Ахмадулиной и других поэтов, а музыку к ним написал Микаэл Таривердиев.","wiki_en":"The Irony of Fate"},{"name":"Бриллиантовая рука","emoji":"💎","meta":["эксцентрическая комедия","1968","Леонид Гайдай"],"description":"Советского туриста по ошибке принимают за курьера контрабандистов и во время заграничного круиза незаметно закладывают ему в гипс на руке партию драгоценностей. Комедия Леонида Гайдая разошлась на цитаты и песни и остаётся одной из самых любимых советских кинокомедий.","fact":"Песня «Остров невезения» из фильма стала настолько популярной, что зажила отдельной от картины жизнью.","wiki_en":"The Diamond Arm"},{"name":"Операция «Ы» и другие приключения Шурика","emoji":"🧱","meta":["эксцентрическая комедия","1965","Леонид Гайдай"],"description":"Три отдельные новеллы рассказывают о незадачливом студенте Шурике, который то помогает бороться с тунеядцем на стройке, то сдаёт экзамен, то срывает план мошенников по ограблению склада. Фильм Гайдая подарил зрителям одну из самых известных ролей троицы жуликов — Труса, Балбеса и Бывалого.","fact":"Трио жуликов — Трус, Балбес и Бывалый — появилось у Гайдая ещё в короткометражках начала 1960-х и стало самостоятельным комическим брендом.","wiki_en":"Operation Y and Other Shurik's Adventures"},{"name":"Кавказская пленница","emoji":"🐴","meta":["эксцентрическая комедия","1966","Леонид Гайдай"],"description":"Приехавший на Кавказ студент Шурик случайно оказывается вовлечён в похищение девушки, которую местный чиновник хочет взять в жёны против её воли, и берётся её спасать. Комедия Леонида Гайдая с той же троицей жуликов стала одной из самых цитируемых советских картин.","fact":"Реплики фильма, включая тост про долгожителей и фразу «птичку жалко», давно живут в русском языке отдельно от картины.","wiki_en":"Kidnapping, Caucasian Style"},{"name":"Иван Васильевич меняет профессию","emoji":"👑","meta":["эксцентрическая комедия","1973","Леонид Гайдай"],"description":"Самодельная машина времени инженера-изобретателя случайно переносит управдома в эпоху Ивана Грозного, а самого царя — в советскую квартиру, что приводит к череде комических путаниц. Экранизация пьесы Михаила Булгакова стала одной из самых любимых советских комедий о путешествиях во времени.","fact":"И грозного царя, и робкого управдома Буншу в фильме играет один и тот же актёр — Юрий Яковлев.","wiki_en":"Ivan Vasilievich: Back to the Future"},{"name":"Джентльмены удачи","emoji":"🎩","meta":["криминальная комедия","1971","Александр Серый"],"description":"Добродушного заведующего детским садом, похожего на матёрого уголовника, привлекают к операции, чтобы он под видом преступника выведал у сокамерников место спрятанного похищенного золотого шлема. Советская комедия о перевоспитании жуликов быстро разошлась на крылатые фразы.","fact":"Многие реплики фильма, включая «Кто ж его посадит, он же памятник», прочно вошли в разговорную речь.","wiki_en":"Gentlemen of Fortune"},{"name":"Москва слезам не верит","emoji":"🏙️","meta":["мелодрама","1980","Владимир Меньшов"],"description":"История трёх молодых провинциалок, приехавших покорять Москву в конце 1950-х, показанная затем спустя двадцать лет, когда их судьбы сложились совсем по-разному. Фильм стал одним из самых любимых в СССР и получил «Оскар» за лучший фильм на иностранном языке.","fact":"Режиссёр Владимир Меньшов не смог поехать на церемонию за наградой и получил свою статуэтку лишь много лет спустя.","wiki_en":"Moscow Does Not Believe in Tears"},{"name":"Служебный роман","emoji":"💼","meta":["лирическая комедия","1977","Эльдар Рязанов"],"description":"Строгая и незаметная для окружающих директриса статистического учреждения неожиданно для себя влюбляется в нового скромного сотрудника, который решает помочь ей стать увереннее и привлекательнее. Советская комедия о позднем чувстве на фоне бюрократической рутины стала одной из самых пересматриваемых.","fact":"Основой фильма стала пьеса «Сослуживцы», написанная Эльдаром Рязановым вместе с Эмилем Брагинским и ранее шедшая в театрах.","wiki_en":"Office Romance"},{"name":"Любовь и голуби","emoji":"🕊️","meta":["лирическая комедия","1984","Владимир Меньшов"],"description":"Простой семьянин из глубинки, поехав на курорт, неожиданно для себя увлекается яркой курортницей и на время уходит из семьи, а жена и дети пытаются вернуть его домой. Комедия по мотивам пьесы стала одной из самых народно любимых советских картин о деревенской жизни.","fact":"Деревенского выпивоху дядю Митю сыграл Сергей Юрский — актёр совсем другого, интеллигентного амплуа, которого ради роли сильно загримировали.","wiki_en":"Love and Doves"},{"name":"Белое солнце пустыни","emoji":"🏜️","meta":["истерн","1970","Владимир Мотыль"],"description":"Демобилизованный красноармеец Сухов, возвращаясь домой через среднеазиатскую пустыню, вынужден взять под опеку целый гарем сбежавшего от преследования басмача и защищать его от бывшего хозяина. Фильм в жанре советского истерна стал классикой и традиционно смотрится космонавтами перед стартом.","fact":"Песню «Ваше благородие, госпожа удача» на стихи Булата Окуджавы спел Павел Луспекаев, сыгравший таможенника Верещагина.","wiki_en":"White Sun of the Desert"},{"name":"Брат","emoji":"🔫","meta":["криминальная драма","1997","Алексей Балабанов"],"description":"Демобилизованный из армии парень приезжает в Петербург к старшему брату и постепенно втягивается в криминальные разборки девяностых, действуя по своим представлениям о справедливости. Фильм Алексея Балабанова стал одним из главных портретов постсоветской эпохи и культовой картиной поколения.","fact":"Музыку группы «Наутилус Помпилиус» из фильма после выхода картины стали прочно ассоциировать с образом главного героя.","wiki_en":"Brother (1997 film)"},{"name":"Брат 2","emoji":"✈️","meta":["криминальная драма","2000","Алексей Балабанов"],"description":"Герой первого фильма отправляется в Америку, чтобы разобраться в судьбе бывшего сослуживца и восстановить справедливость, сталкиваясь с чужой и не всегда понятной ему страной. Сиквел культовой картины Балабанова подарил зрителям ещё больше крылатых фраз и закрепил статус фильма как поколенческого высказывания.","fact":"Диалог о том, в чём сила — в деньгах или в правде, стал одной из самых узнаваемых сцен в русском кино.","wiki_en":"Brother 2"},{"name":"Сталкер","emoji":"🌫️","meta":["философская фантастика","1979","Андрей Тарковский"],"description":"Проводник по прозвищу Сталкер ведёт писателя и учёного через таинственную и опасную Зону к комнате, где, по легенде, исполняются самые сокровенные желания. Экранизация повести братьев Стругацких превратилась у Тарковского в медитативную притчу о вере, желании и человеческой природе.","fact":"Значительную часть материала пришлось переснимать заново из-за брака при обработке плёнки, и производство растянулось на годы.","wiki_en":"Stalker (1979 film)"}];
